package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Whitelist;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen0Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(Whitelist.basic());
    }

    @Test
    public void testValidDocument() {
        String html = "<html><body><p>Valid content</p></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithUnsafeTag() {
        String html = "<html><body><script>alert('xss');</script></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithUnsafeAttribute() {
        String html = "<html><body><a href='javascript:alert(\"xss\")'>Link</a></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testEmptyDocument() {
        Document dirtyDocument = Jsoup.parse("");
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testNullDocument() {
        cleaner.isValid(null);
    }

    @Test
    public void testDocumentWithOnlySafeTags() {
        String html = "<html><body><p>Safe content</p><br/></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithMixedContent() {
        String html = "<html><body><p>Safe content</p><script>alert('xss');</script></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithOnlyUnsafeTags() {
        String html = "<html><body><script>alert('xss');</script></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertFalse(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithNestedTags() {
        String html = "<html><body><div><p>Safe content</p></div></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertTrue(cleaner.isValid(dirtyDocument));
    }

    @Test
    public void testDocumentWithNestedUnsafeTags() {
        String html = "<html><body><div><script>alert('xss');</script></div></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        assertFalse(cleaner.isValid(dirtyDocument));
    }
}
